-- Generated from data/tn-christian-schools-2026-27.json (TDOE Non-Public Schools Directory 2026-27, Christian schools, Categories I-IV).
-- Run after migrations: psql $DATABASE_URL -f supabase/seed-schools.sql
on conflict (slug) do update set name = excluded.name, city = excluded.city, grades = excluded.grades, email_domain = excluded.email_domain, alt_email_domain = excluded.alt_email_domain, accreditor = excluded.accreditor, county = excluded.county, region = excluded.region, tdoe_category = excluded.tdoe_category;
